import os
from bioblend.galaxy import GalaxyInstance
key_path=os.environ['GALAXY_API_KEY_FILE']
with open(key_path) as f: key=f.read().strip()
gi=GalaxyInstance(os.environ['GALAXY_URL'], key=key)
tool='toolshed.g2.bx.psu.edu/repos/devteam/column_maker/Add_a_column1/2.1+galaxy0'
x=gi.tools.show_tool(tool, io_details=True)
def walk(items,p=''):
    for z in items:
        name=z.get('name','')
        q=(p+'|'+name).strip('|')
        print(q,z.get('type'),repr(z.get('value')),repr(z.get('options'))[:200])
        for k in ('inputs','cases'):
            y=z.get(k)
            if isinstance(y,list):
                if k=='cases':
                    for c in y:
                        walk(c.get('inputs',[]),q)
                else: walk(y,q)
walk(x.get('inputs',[]))
